const loading = ref(false);

const getBinCard = async (id) => {
    loading.value = true;

    try {
        const response = await axiosInstance.get(`bin-cards?store_item_id=${id}`);

        if (!response.data || response.data.length === 0) {
            bincard.value = [];
            bincardName.value = '';
            finalBalance.value = '0.00';
            totalReceived.value = '0.00';
            totalIssued.value = '0.00';

            showError('There is no bin card information for the selected item.');
            return;
        }

        const data = response.data[0];

        bincardName.value = data.store_item?.item?.name || '';

        let runningBalance = 0;
        let totalReceivedAmount = 0;
        let totalIssuedAmount = 0;

        bincard.value = data.items.map((item, index) => {
            const received = parseFloat(item.received) || 0;
            const issued = parseFloat(item.issued) || 0;

            totalReceivedAmount += received;
            totalIssuedAmount += issued;
            runningBalance += received - issued;

            return {
                id: item.id,
                SNo: index + 1,
                date: formatDate(item.date || item.created_at),
                ref_no: item.ref_no || '--',
                received_Qty: received ? `${received} ${data.unit || ''}` : '--',
                issued_Qty: issued ? `${issued} ${data.unit || ''}` : '--',
                balance_Qty: `${runningBalance} ${data.unit || ''}`,
                remark: item.remark || '--',
                authorized_by: item.issuer?.name || 'N/A'
            };
        });

        finalBalance.value = `${runningBalance} ${data.unit || ''}`;
        totalReceived.value = `${totalReceivedAmount} ${data.unit || ''}`;
        totalIssued.value = `${totalIssuedAmount} ${data.unit || ''}`;

    } catch (error) {
        console.log(error);
        showError(error.message);
    } finally {
        loading.value = false;
    }
};



